inline float sample(int shape,double phase,float tension=0,bool mirrorH=false,bool mirrorV=false,float slopePercent=0) noexcept {
    if(!std::isfinite(phase))phase=0;
    if(mirrorH)phase=1-phase;
    phase-=std::floor(phase);
    const double position=phase*nodeCount;
    const int index=int(position);const double f=position-index;
    const auto* row=nodes[std::clamp(shape,0,waveCount-1)];
    constexpr int mask=nodeCount-1;
    double p0,p1,p2,p3;
    if(slopePercent==0){p0=row[(index-1)&mask];p1=row[index&mask];p2=row[(index+1)&mask];p3=row[(index+2)&mask];}
    else {p0=spline::node(shape,index-1,slopePercent);p1=spline::node(shape,index,slopePercent);
        p2=spline::node(shape,index+1,slopePercent);p3=spline::node(shape,index+2,slopePercent);}
    // Bend non-negative nodes before interpolation. Overshoot remains signed,
    // so fractional CURVE never raises a negative interpolated gain to a power.
    if(tension!=0){const double exponent=std::exp2(-double(tension)/70);
        p0=std::pow(p0,exponent);p1=std::pow(p1,exponent);
        p2=std::pow(p2,exponent);p3=std::pow(p3,exponent);}
    const double a1=.5*(p2-p0),a2=p0-2.5*p1+2*p2-.5*p3;
    const double a3=.5*(p3-p0)+1.5*(p1-p2);
    const float gain=float(p1+f*(a1+f*(a2+f*a3)));
    return mirrorV?1-gain:gain;
}
// END=1 endpoint policy measured on all16 factory forms. Forms13/14 hold
// unity; all others hold their periodic phase-zero gain. Internal SLOPE
// changes are evaluated normally, corroborated by a saved Wave1 geometry.
// Mirrors exchange/flip these geometric endpoint values.
inline float sampleEndpoint(int shape,double rawPhase,float tension=0,bool mirrorH=false,
                            bool mirrorV=false,float slopePercent=0) noexcept {
    const bool rightEndpoint=mirrorH?rawPhase==0:rawPhase==1;
    if(rightEndpoint&&(shape==12||shape==13))return mirrorV?0.f:1.f;
    return sample(shape,rawPhase,tension,mirrorH,mirrorV,slopePercent);
}

